#include <cstdio>
#include <cstring>
#include <vector>
using namespace std;

int n, m, ans;
int a[11][100001];

void dfs(int x, vector<int>& count) {
    if(x >= n) return;

    int sum = 0;
    for(int i = 0; i < m; i++) {
        sum += (count[i] > n / 2) ? count[i] : (n - count[i]); // Efficient calculation
    }

    if(sum > ans) ans = sum;
    dfs(x + 1, count);

    for(int i = 0; i < m; i++) {
        count[i] += (a[x][i] == 0) ? 1 : -1; // Update count
        a[x][i] ^= 1; // Toggle
    }
    dfs(x + 1, count);

    for(int i = 0; i < m; i++) {
        count[i] += (a[x][i] == 0) ? 1 : -1; // Revert count update
        a[x][i] ^= 1; // Revert back
    }
}

int main() {
    while(~scanf("%d%d", &n, &m)) {
        if(n == 0 && m == 0) break;
        memset(a, 0, sizeof(a));
        ans = 0;
        vector<int> count(m, 0);
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                scanf("%d", &a[i][j]);
                count[j] += a[i][j]; // Initialize count
            }
        }
        dfs(0, count);
        printf("%d\n", ans);
    }
    return 0;
}

